    if (getTrip().getNumberOfSeats() < getNumberOfSeats())
    {
      return false;
    }

    long diffMillis = getTrip().getDepartureTime().getTime() - getBookingDate().getTime();
    if (diffMillis <= 2L * 60L * 60L * 1000L)
    {
      return false;
    }

    Calendar bookingCal = Calendar.getInstance();
    bookingCal.setTime(getBookingDate());
    int bookingYear = bookingCal.get(Calendar.YEAR);
    int bookingDayOfYear = bookingCal.get(Calendar.DAY_OF_YEAR);

    for (Booking other : getCustomer().getBookings())
    {
      if (other == this)
      {
        continue;
      }

      if (other.getBookingDate() == null || other.getTrip() == null)
      {
        continue;
      }

      Calendar otherCal = Calendar.getInstance();
      otherCal.setTime(other.getBookingDate());
      if (bookingYear == otherCal.get(Calendar.YEAR) &&
          bookingDayOfYear == otherCal.get(Calendar.DAY_OF_YEAR))
      {
        if (overlapsWith(other.getTrip()))
        {
          return false;
        }
      }
    }

    updateTripSeats();
    return true;
    
